    :param string: String
    :str string: str
    :return: True or False
    """
def convert_to_bool(string: Any) -> object {
    if isinstance(string, bool) {
        return string;
    }
    return (string in ['true', 'True', '1']);
}

"""
    Find a string to represent a scenario from it's number (or None in the case of baseline).

    Args:
        scenario: The scenario value or None for baseline
    Returns:
        The string representing the scenario
    """
def find_scenario_string_from_number(scenario: Any) -> object {
    if (scenario == 0) {
        return 'baseline';
    } elif (scenario == 16) {
        return 'no transmission';
    } else {
        return ('scenario_' + str(scenario));
    }
}

